use std::sync::Arc;  use serde_json::{json, Value}; use tracing::info;  use crate::engine::ipc::EngineBridge; use crate::engine::process; use crate::mode;  pub async fn tab_command(bridge: &EngineBridge, body: &Value) -> anyhow::Result<Value> {     let op = body.get("op").and_then(|v| v.as_str()).unwrap_or("");     match op {         "list" => bridge.call("tab.list", json!({})).await,         "activate" => {             let tab_id = tab_id_field(body)?;             bridge                 .call("tab.activate", json!({ "tabId": tab_id }))                 .await?;             Ok(json!({ "ok": true, "tab_id": tab_id }))         }         "new" => {             let url = body.get("url").and_then(|v| v.as_str());             let mut params = json!({});             if let Some(u) = url {                 params["url"] = json!(u);             }             bridge.call("tab.new", params).await         }         "close" => {             let tab_id = tab_id_field(body)?;             bridge                 .call("tab.close", json!({ "tabId": tab_id }))                 .await?;             Ok(json!({ "ok": true, "tab_id": tab_id }))         }         _ => anyhow::bail!("unknown browser.tab op: {op}"),     } }  fn tab_id_field(body: &Value) -> anyhow::Result<&str> {     body.get("tab_id")         .or_else(|| body.get("tabId"))         .and_then(|v| v.as_str())         .ok_or_else(|| anyhow::anyhow!("tab_id required")) }  async fn handle_tab_ws(body: Value) -> anyhow::Result<Value> {     let st = crate::browser_state::global().ok_or_else(|| anyhow::anyhow!("browser state not init"))?;     let headless = mode::headless_from_config();     let slot_id = body         .get("slot_id")         .and_then(|v| v.as_str())         .unwrap_or("default");     let bridge = process::ensure_engine(&st, headless, slot_id).await?;     tab_command(&bridge, &body).await }  pub fn register_tab_handler() {     c_remote_core::task_run::set_browser_tab_handler(Arc::new(|body| {         Box::pin(async move {             let op = body.get("op").and_then(|v| v.as_str()).unwrap_or("").to_string();             let result = handle_tab_ws(body).await;             match &result {                 Ok(v) => info!(op = %op, result = %v, "c35.browser.tab ok"),                 Err(e) => tracing::warn!(op = %op, "c35.browser.tab failed: {e}"),             }             result         })     })); }